用户目标：去协和医院堵不堵，然后把路况存成笔记「旅行计划」，下周三 19:30用路况提醒我，这些都办完之后，给chenjing@example.com发封邮件，标题「报销材料」，正文「项目已完成七成，预计月底交付」

{
  "tasks": [
    {
      "description": "查询前往协和医院的路况",
      "id": "task_1",
      "required_tool": "system.query_traffic",
      "arguments": {
        "destination": "协和医院"
      }
    },
    {
      "description": "将路况信息存为笔记「旅行计划」",
      "id": "task_2",
      "required_tool": "system.create_note",
      "arguments": {
        "title": "旅行计划",
        "content": "{\"$from\": \"task_1\"}"
      }
    },
    {
      "description": "下周三 19:30 用路况提醒用户",
      "id": "task_3",
      "required_tool": "system.create_reminder",
      "arguments": {
        "content": "{\"$from\": \"task_1\"}",
        "when": "下周三 19:30"
      }
    },
    {
      "description": "发送邮件到 chenjing@example.com",
      "id": "task_4",
      "required_tool": "system.send_email",
      "arguments": {
        "to": "chenjing@example.com",
        "subject": "报销材料",
        "body": "项目已完成七成，预计月底交付"
      }
    }
  ]
}

